command:
set -euo pipefail
for f in /home/ai-core-node/.local/share/clay-local-bridge/bin/daemon.py /home/ai-core-node/.claude/star/local_bridge_daemon.py; do echo ===FILE:$f===; sha256sum "$f" || true; grep -nE 'STATE_DIR|REPO[[:space:]]*=|DB[[:space:]]*=|CONTROL_BRANCH|RESULTS_BRANCH|QUEUE[[:space:]]*=|poll_once|checkout.*-B|INSERT.*done|sync_and_push_results' "$f" 2>/dev/null | head -120 || true; done
echo ===PIDS===
for p in 2495 959674; do if [ -r /proc/$p/cmdline ]; then echo PID=$p; tr '\0' ' ' < /proc/$p/cmdline; echo; readlink -f /proc/$p/cwd || true; fi; done
echo ===OPEN_REPO_FILES===
command -v lsof >/dev/null && lsof +D /home/ai-core-node/.claude/star/local_bridge_state/repo 2>/dev/null | head -80 || true
